options.css:
.card { font-family: inherit; color: #c7c9d1; height: 100%; box-sizing: border-box;
  padding: 4px 8px; display: flex; flex-direction: column; justify-content: flex-start; gap: 2px; }
.head { display: flex; justify-content: space-between; align-items: baseline; }
.name { font-weight: 600; font-size: 13px; color: #e4e5ea; }
.role { font-size: 9px; padding: 1px 6px; border-radius: 3px; background: #1d2230; color: #7fa3e8; }
.role.cp { background: #16321f; color: #5fc77e; }
.ip { font-size: 10.5px; color: #8a8d98; }
.grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 3px 10px; font-size: 12px; margin-top: 3px; }
.grid > div { display: flex; flex-direction: column; }
.lbl { font-size: 9.5px; color: #6b6d76; text-transform: uppercase; letter-spacing: .3px; }
#n-ready.ok { color: #5fc77e; } #n-ready.bad { color: #e05b5b; }

options.onRender:
function numField(refId) {
  var frame = data.series.filter(function (s) { return s.refId === refId; })[0];
  if (!frame) { return null; }
  var field = frame.fields.filter(function (f) { return f.type === "number"; })[0];
  if (!field || field.values.length === 0) { return null; }
  var vals = field.values;
  return vals.get ? vals.get(vals.length - 1) : vals[vals.length - 1];
}
function fmtBytes(b) {
  if (b == null) { return "—"; }
  return (b / 1e9).toFixed(1) + " GB";
}
function fmtAge(s) {
  if (s == null) { return "—"; }
  var d = s / 86400;
  if (d >= 365) { return (d / 365).toFixed(1) + "y"; }
  if (d >= 7) { return (d / 7).toFixed(1) + "w"; }
  return d.toFixed(1) + "d";
}

var cpuCores = numField("A");
var cpuPct = numField("B");
var ramUsed = numField("C");
var ramTotal = numField("D");
var ready = numField("E");
var taints = numField("F");
var ageSec = numField("G");

htmlNode.querySelector("#n-cpu").textContent = (cpuCores != null ? cpuCores + "c" : "—")
  + (cpuPct != null ? " · " + cpuPct.toFixed(1) + "%" : "");
htmlNode.querySelector("#n-ram").textContent = (ramUsed != null && ramTotal != null)
  ? fmtBytes(ramUsed) + " / " + fmtBytes(ramTotal) : "—";
htmlNode.querySelector("#n-age").textContent = fmtAge(ageSec);
var readyEl = htmlNode.querySelector("#n-ready");
readyEl.textContent = ready === 1 ? "Ready" : "NotReady";
readyEl.className = ready === 1 ? "ok" : "bad";
htmlNode.querySelector("#n-taints").textContent = taints != null ? taints : "—";

