  return (b / 1e9).toFixed(1) + " GB";
}
function fmtAge(s) {
  if (s == null) { return "—"; }
  var d = s / 86400;
  if (d >= 365) { return (d / 365).toFixed(1) + "y"; }
  if (d >= 7) { return (d / 7).toFixed(1) + "w"; }
  return d.toFixed(1) + "d";
}

var cpuCores = numField("A");
var cpuPct = numField("B");
var ramUsed = numField("C");
var ramTotal = numField("D");
var ready = numField("E");
var taints = numField("F");
var ageSec = numField("G");

htmlNode.querySelector("#n-cpu").textContent = (cpuCores != null ? cpuCores + "c" : "—")
  + (cpuPct != null ? " · " + cpuPct.toFixed(1) + "%" : "");
htmlNode.querySelector("#n-ram").textContent = (ramUsed != null && ramTotal != null)
  ? fmtBytes(ramUsed) + " / " + fmtBytes(ramTotal) : "—";
htmlNode.querySelector("#n-age").textContent = fmtAge(ageSec);
var readyEl = htmlNode.querySelector("#n-ready");
readyEl.textContent = ready === 1 ? "Ready" : "NotReady";
readyEl.className = ready === 1 ? "ok" : "bad";
htmlNode.querySelector("#n-taints").textContent = taints != null ? taints : "—";
